// This function builds the final SQL string at runtime with dates relative to the server's start time.
static std::string generateShowtimesSQL() {
    if (showtime_seeds.empty()) {
        return "";
    }

    // This uses modern C++ to get the current date in a timezone-neutral way.
    // It correctly handles all date and time calculations.
    const auto now = std::chrono::system_clock::now();
    const auto today = std::chrono::time_point_cast<std::chrono::duration<int, std::ratio<86400>>>(now);

    std::stringstream sql;
    sql << "INSERT INTO Showtimes (MovieID, VenueID, AuditoriumID, ShowtimeDateTime) VALUES ";

    for (size_t i = 0; i < showtime_seeds.size(); ++i) {
        const auto& seed = showtime_seeds[i];
        
        // Calculate the target date by adding the offset (0 for today, 1 for tomorrow, etc.)
        const auto target_day = today + std::chrono::duration<int, std::ratio<86400>>(seed.day_offset);
        
        // Format the date into the required "YYYY-MM-DD" string format
        std::time_t tt = std::chrono::system_clock::to_time_t(target_day);
        std::tm tm = *std::gmtime(&tt);

        sql << "("
            << seed.movie_id << ", "
            << seed.venue_id << ", "
            << seed.auditorium_id << ", "
            << "'" << (tm.tm_year + 1900)
            << "-" << std::setfill('0') << std::setw(2) << (tm.tm_mon + 1)
            << "-" << std::setfill('0') << std::setw(2) << tm.tm_mday
            << " " << seed.time << "')";

        if (i < showtime_seeds.size() - 1) {
            sql << ",\n";
        }
    }
    sql << ";";
    return sql.str();
}

